import sys

def main():
    s = sys.stdin.readline().strip()

    matching = {')': '(', ']': '[', '>': '<'}
    opening = {'(', '[', '<'}
    stack = []

    for ch in s:
        if ch in opening:
            stack.append(ch)
        else:
            if not stack or stack[-1] != matching[ch]:
                print("No")
                return
            stack.pop()

    print("Yes" if not stack else "No")

if __name__ == "__main__":
    main()
